import { ProfilePatch } from './types';

const MAX_DISPLAY_NAME = 40;
const MAX_TAGS = 5;
const MAX_TAG = 12;

function invalid(): never {
  throw new Error('invalid profile');
}

// Reads an own data property. Returns undefined when the key is absent.
// Accessor properties are rejected so that no caller code runs during parsing.
function readData(obj: object, key: 'displayName' | 'tags'): { value: unknown } | undefined {
  const desc = Object.getOwnPropertyDescriptor(obj, key);
  if (desc === undefined) return undefined;
  if (!('value' in desc)) invalid();
  return { value: desc.value };
}

function parseDisplayName(value: unknown): string | null {
  if (value === null) return null;
  if (typeof value !== 'string') invalid();
  const trimmed = value.trim();
  if (trimmed.length < 1 || trimmed.length > MAX_DISPLAY_NAME) invalid();
  return trimmed;
}

function parseTags(value: unknown): string[] {
  if (value === null) return [];
  if (!Array.isArray(value)) invalid();
  if (value.length > MAX_TAGS) invalid();
  // Always build a fresh array so the caller's array is never stored.
  const tags: string[] = [];
  const seen = new Set<string>();
  for (let i = 0; i < value.length; i++) {
    const raw: unknown = value[i]; // holes read as undefined and are rejected
    if (typeof raw !== 'string') invalid();
    const trimmed = raw.trim();
    if (trimmed.length < 1 || trimmed.length > MAX_TAG) invalid();
    if (seen.has(trimmed)) invalid();
    seen.add(trimmed);
    tags.push(trimmed);
  }
  return tags;
}

export function parseProfile(input: unknown): ProfilePatch {
  if (typeof input !== 'object' || input === null || Array.isArray(input)) invalid();
  const proto = Object.getPrototypeOf(input);
  if (proto !== Object.prototype && proto !== null) invalid();

  // Any own key other than displayName/tags (including symbols and
  // non-enumerable keys) makes the input invalid.
  for (const key of Reflect.ownKeys(input)) {
    if (key !== 'displayName' && key !== 'tags') invalid();
  }

  let displayName: ProfilePatch['displayName'] = { kind: 'keep' };
  let tags: ProfilePatch['tags'] = { kind: 'keep' };
  const rawName = readData(input, 'displayName');
  if (rawName !== undefined) displayName = { kind: 'set', value: parseDisplayName(rawName.value) };
  const rawTags = readData(input, 'tags');
  if (rawTags !== undefined) tags = { kind: 'set', value: parseTags(rawTags.value) };
  return { displayName, tags };
}

